1	package contractsentinel
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"path/filepath"
8		"strings"
9		"sync"
10		"testing"
11	)
12	
13	func sampleArtifact() Artifact {
14		return Artifact{Name: "Vault", ABI: `[{"name":"withdraw"}]`, Bytecode: "0x6080", Source: "Vault.sol"}
15	}
16	
17	func sampleRules() []Rule {
18		return []Rule{
19			{ID: "reentrancy-guard", Kind: "static", Severity: "high", Invariant: "no-reentrant-withdraw", Version: "1.0.0"},
20			{ID: "access-control", Kind: "static", Severity: "medium", Invariant: "owner-only-withdraw", RequiresABI: true, Version: "2.1.0"},
21			{ID: "invariant-preserved", Kind: "symbolic", Severity: "critical", Invariant: "balance-monotonic", Version: "0.9.0"},
22		}
23	}
24	
25	func sampleInvariants() map[string]bool {
26		return map[string]bool{
27			"no-reentrant-withdraw": false,
28			"owner-only-withdraw":   true,
29			"balance-monotonic":     false,
30		}
31	}
32	
33	// --- ArtifactHash ---
34	
35	func TestArtifactHashDeterministic(t *testing.T) {
36		a := sampleArtifact()
37		if ArtifactHash(a) != ArtifactHash(a) {
38			t.Fatal("artifact hash is not deterministic")
39		}
40	}
41	
42	func TestArtifactHashFieldBoundaries(t *testing.T) {
43		// Different splits of the same concatenation must not collide.
44		a := Artifact{ABI: "ab", Bytecode: "c", Source: ""}
45		b := Artifact{ABI: "a", Bytecode: "bc", Source: ""}
46		if ArtifactHash(a) == ArtifactHash(b) {
47			t.Fatal("artifact hash collided across field boundaries")
48		}
49	}
50	
51	func TestArtifactHashNameExcluded(t *testing.T) {
52		a := Artifact{Name: "Vault", ABI: "x", Bytecode: "y", Source: "z"}
53		b := Artifact{Name: "Other", ABI: "x", Bytecode: "y", Source: "z"}
54		if ArtifactHash(a) != ArtifactHash(b) {
55			t.Fatal("name must not participate in the artifact hash")
56		}
57	}
58	
59	func TestArtifactHashSourceIsValue(t *testing.T) {
60		// Source is hashed as a field value; a source string that looks like a
61		// path must never be read from disk.
62		a := Artifact{ABI: "x", Bytecode: "y", Source: "Vault.sol"}
63		b := Artifact{ABI: "x", Bytecode: "y", Source: "other/Vault.sol"}
64		if ArtifactHash(a) == ArtifactHash(b) {
65			t.Fatal("different source values must hash differently")
66		}
67	}
68	
69	// --- BuildReport statuses ---
70	
71	func TestBuildReportStatuses(t *testing.T) {
72		report, err := BuildReport(sampleArtifact(), sampleRules(), sampleInvariants(), nil)
73		if err != nil {
74			t.Fatal(err)
75		}
76		statusByID := map[string]string{}
77		for _, r := range report.Rules {
78			statusByID[r.ID] = r.Status
79		}
80		if statusByID["reentrancy-guard"] != StatusDefect {
81			t.Errorf("reentrancy-guard = %q, want %q", statusByID["reentrancy-guard"], StatusDefect)
82		}
83		if statusByID["access-control"] != StatusPass {
84			t.Errorf("access-control = %q, want %q", statusByID["access-control"], StatusPass)
85		}
86		if statusByID["invariant-preserved"] != StatusDefect {
87			t.Errorf("invariant-preserved = %q, want %q", statusByID["invariant-preserved"], StatusDefect)
88		}
89	}
90	
91	func TestBuildReportUnchecked(t *testing.T) {
92		// Missing invariant value => 未检查, not a defect.
93		invariants := map[string]bool{"no-reentrant-withdraw": false}
94		report, err := BuildReport(sampleArtifact(), sampleRules(), invariants, nil)
95		if err != nil {
96			t.Fatal(err)
97		}
98		statusByID := map[string]string{}
99		for _, r := range report.Rules {
100			statusByID[r.ID] = r.Status
101		}
102		if statusByID["access-control"] != StatusUnchecked {
103			t.Errorf("access-control = %q, want %q", statusByID["access-control"], StatusUnchecked)
104		}
105		if statusByID["invariant-preserved"] != StatusUnchecked {
106			t.Errorf("invariant-preserved = %q, want %q", statusByID["invariant-preserved"], StatusUnchecked)
107		}
108		for _, f := range report.Findings {
109			if f.RuleID == "access-control" || f.RuleID == "invariant-preserved" {
110				t.Errorf("unchecked rule produced a finding: %+v", f)
111			}
112		}
113	}
114	
115	func TestBuildReportFindingsBind(t *testing.T) {
116		report, err := BuildReport(sampleArtifact(), sampleRules(), sampleInvariants(), nil)
117		if err != nil {
118			t.Fatal(err)
119		}
120		if len(report.Findings) != 2 {
121			t.Fatalf("findings = %d, want 2", len(report.Findings))
122		}
123		hash := ArtifactHash(sampleArtifact())
124		for _, f := range report.Findings {
125			if f.ArtifactHash != hash {
126				t.Errorf("finding %s artifact hash = %q, want %q", f.RuleID, f.ArtifactHash, hash)
127			}
128			if f.Version == "" {
129				t.Errorf("finding %s has empty version", f.RuleID)
130			}
131			if f.Evidence == "" {
132				t.Errorf("finding %s has empty evidence", f.RuleID)
133			}
134		}
135	}
136	
137	func TestBuildReportEmptyRules(t *testing.T) {
138		report, err := BuildReport(sampleArtifact(), nil, sampleInvariants(), nil)
139		if err != nil {
140			t.Fatal(err)
141		}
142		if len(report.Rules) != 0 || len(report.Findings) != 0 {
143			t.Fatalf("empty rules should give empty report, got %+v", report)
144		}
145		if report.ReportID == "" {
146			t.Fatal("empty rules report still needs an id")
147		}
148	}
149	
150	// --- BuildReport input refusal ---
151	
152	func TestBuildReportRequiresABIMissing(t *testing.T) {
153		rules := []Rule{{ID: "r1", Kind: "static", Invariant: "inv", RequiresABI: true, Version: "1"}}
154		_, err := BuildReport(Artifact{Name: "A", ABI: "", Bytecode: "0x1"}, rules, map[string]bool{"inv": false}, nil)
155		if err == nil {
156			t.Fatal("expected error for missing ABI")
157		}
158	}
159	
160	func TestBuildReportSymbolicMissingBytecode(t *testing.T) {
161		rules := []Rule{{ID: "r1", Kind: "symbolic", Invariant: "inv", Version: "1"}}
162		_, err := BuildReport(Artifact{Name: "A", ABI: "abi", Bytecode: ""}, rules, map[string]bool{"inv": false}, nil)
163		if err == nil {
164			t.Fatal("expected error for missing bytecode")
165		}
166	}
167	
168	func TestBuildReportDuplicateRuleID(t *testing.T) {
169		rules := []Rule{
170			{ID: "r1", Kind: "static", Invariant: "a", Version: "1"},
171			{ID: "r1", Kind: "static", Invariant: "b", Version: "1"},
172		}
173		_, err := BuildReport(sampleArtifact(), rules, nil, nil)
174		if err == nil || !strings.Contains(err.Error(), "duplicate") {
175			t.Fatalf("expected duplicate rule id error, got %v", err)
176		}
177	}
178	
179	func TestBuildReportEmptyRuleID(t *testing.T) {
180		rules := []Rule{{ID: "", Kind: "static", Invariant: "a", Version: "1"}}
181		_, err := BuildReport(sampleArtifact(), rules, nil, nil)
182		if err == nil {
183			t.Fatal("expected error for empty rule id")
184		}
185	}
186	
187	func TestBuildReportEmptyVersion(t *testing.T) {
188		rules := []Rule{{ID: "r1", Kind: "static", Invariant: "a", Version: ""}}
189		_, err := BuildReport(sampleArtifact(), rules, nil, nil)
190		if err == nil {
191			t.Fatal("expected error for empty version")
192		}
193	}
194	
195	func TestBuildReportEmptyArtifactName(t *testing.T) {
196		_, err := BuildReport(Artifact{ABI: "x", Bytecode: "y"}, sampleRules(), nil, nil)
197		if err == nil {
198			t.Fatal("expected error for empty artifact name")
199		}
200	}
201	
202	// --- ParseAuditInput ---
203	
204	func TestParseAuditInputValid(t *testing.T) {
205		input := `{
206			"artifact": {"name":"Vault","abi":"abi","bytecode":"0x1","source":"Vault.sol"},
207			"rules": [{"id":"r1","kind":"static","severity":"high","invariant":"inv","requiresABI":true,"version":"1.0.0"}],
208			"invariants": {"inv": false},
209			"checks": [{"artifactHash":"abc","ruleId":"r1","version":"1.0.0","status":"通过","note":""}]
210		}`
211		artifact, rules, invariants, checks, err := ParseAuditInput([]byte(input))
212		if err != nil {
213			t.Fatal(err)
214		}
215		if artifact.Name != "Vault" || artifact.ABI != "abi" || artifact.Bytecode != "0x1" || artifact.Source != "Vault.sol" {
216			t.Errorf("artifact = %+v", artifact)
217		}
218		if len(rules) != 1 || rules[0].ID != "r1" || rules[0].Version != "1.0.0" || !rules[0].RequiresABI {
219			t.Errorf("rules = %+v", rules)
220		}
221		if len(invariants) != 1 || invariants["inv"] {
222			t.Errorf("invariants = %+v", invariants)
223		}
224		if len(checks) != 1 {
225			t.Fatalf("checks = %+v", checks)
226		}
227		if checks[0].ArtifactHash != "abc" || checks[0].RuleID != "r1" || checks[0].Version != "1.0.0" ||
228			checks[0].Status != StatusPass || checks[0].Note != "" {
229			t.Errorf("check = %+v", checks[0])
230		}
231	}
232	
233	func TestParseAuditInputInvalidJSON(t *testing.T) {
234		if _, _, _, _, err := ParseAuditInput([]byte(`{not json`)); err == nil {
235			t.Fatal("expected invalid JSON error")
