1	package main
2	
3	import (
4		"bytes"
5		"os"
6		"os/exec"
7		"path/filepath"
8		"strings"
9		"testing"
10	)
11	
12	// auditBinary builds the CLI into a temp file once and returns its path. The
13	// tests exercise the real process boundary: exit status, stdout and stderr are
14	// observed exactly as an operator would see them.
15	func auditBinary(t *testing.T) string {
16		t.Helper()
17		bin := filepath.Join(t.TempDir(), "contractsentinel")
18		cmd := exec.Command("go", "build", "-o", bin, ".")
19		var out bytes.Buffer
20		cmd.Stdout = &out
21		cmd.Stderr = &out
22		if err := cmd.Run(); err != nil {
23			t.Fatalf("build failed: %v\n%s", err, out.String())
24		}
25		return bin
26	}
27	
28	// writeInput stores a JSON submission and returns its path.
29	func writeInput(t *testing.T, dir, name, content string) string {
30		t.Helper()
31		path := filepath.Join(dir, name)
32		if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
33			t.Fatal(err)
34		}
35		return path
36	}
37	
38	const nullInvariantInput = `{
39		"artifact": {"name":"Vault","abi":"abi","bytecode":"0x1","source":"Vault.sol"},
40		"rules": [{"id":"invariant-preserved","kind":"symbolic","severity":"critical","invariant":"balance-monotonic","version":"0.9.0"}],
41		"invariants": {"balance-monotonic": null}
42	}`
43	
44	const validInvariantInput = `{
45		"artifact": {"name":"Vault","abi":"abi","bytecode":"0x1","source":"Vault.sol"},
46		"rules": [{"id":"invariant-preserved","kind":"symbolic","severity":"critical","invariant":"balance-monotonic","version":"0.9.0"}],
47		"invariants": {"balance-monotonic": false}
48	}`
49	
50	// null 不变式：非零退出、原因进 stderr、stdout 不得出现成功报告。
51	func TestCLIAuditNullInvariantFailsCleanly(t *testing.T) {
52		bin := auditBinary(t)
53		work := t.TempDir()
54		input := writeInput(t, work, "in.json", nullInvariantInput)
55		store := filepath.Join(work, "reports")
56	
57		cmd := exec.Command(bin, "audit", "--input", input, "--store", store)
58		var stdout, stderr bytes.Buffer
59		cmd.Stdout = &stdout
60		cmd.Stderr = &stderr
61		err := cmd.Run()
62	
63		if err == nil {
64			t.Fatal("audit must exit non-zero for a null invariant value")
65		}
66		if exitErr, ok := err.(*exec.ExitError); ok && exitErr.ExitCode() == 0 {
67			t.Fatalf("exit code = 0, want non-zero")
68		}
69		if strings.Contains(stdout.String(), "reportId") || strings.Contains(stdout.String(), "发现缺陷") {
70			t.Fatalf("stdout must not contain a success report:\n%s", stdout.String())
71		}
72		if !strings.Contains(stderr.String(), "balance-monotonic") {
73			t.Fatalf("stderr must name the invariant:\n%s", stderr.String())
74		}
75		if !strings.Contains(stderr.String(), "boolean") {
76			t.Fatalf("stderr must say the value must be a boolean:\n%s", stderr.String())
77		}
78	}
79	
80	// 解析失败时不得创建尚不存在的报告目录或任何文件。
81	func TestCLIAuditNullInvariantCreatesNoStore(t *testing.T) {
82		bin := auditBinary(t)
83		work := t.TempDir()
84		input := writeInput(t, work, "in.json", nullInvariantInput)
85		store := filepath.Join(work, "nested", "reports")
86	
87		cmd := exec.Command(bin, "audit", "--input", input, "--store", store)
88		if out, err := cmd.CombinedOutput(); err == nil {
89			t.Fatalf("audit must fail, output:\n%s", out)
90		}
91		if _, err := os.Stat(store); !os.IsNotExist(err) {
92			t.Fatalf("failure must not create the report store: %v", err)
93		}
94	}
95	
96	// 目录中已有报告时，一次失败的提交必须保持原有内容原样不变。
97	func TestCLIAuditNullInvariantKeepsExistingReports(t *testing.T) {
98		bin := auditBinary(t)
99		work := t.TempDir()
100		validInput := writeInput(t, work, "valid.json", validInvariantInput)
101		store := filepath.Join(work, "reports")
102	
103		// Produce one real report first.
104		setup := exec.Command(bin, "audit", "--input", validInput, "--store", store)
105		if out, err := setup.CombinedOutput(); err != nil {
106			t.Fatalf("valid audit setup failed: %v\n%s", err, out)
107		}
108		before, err := listFiles(store)
109		if err != nil {
110			t.Fatal(err)
111		}
112		if len(before) != 1 {
113			t.Fatalf("setup expected 1 report, got %d: %v", len(before), before)
114		}
115		existingPath := filepath.Join(store, before[0])
116		existingBytes, err := os.ReadFile(existingPath)
117		if err != nil {
118			t.Fatal(err)
119		}
120	
121		// The invalid submission must fail and change nothing.
122		badInput := writeInput(t, work, "bad.json", nullInvariantInput)
123		fail := exec.Command(bin, "audit", "--input", badInput, "--store", store)
124		if out, err := fail.CombinedOutput(); err == nil {
125			t.Fatalf("invalid audit must fail, output:\n%s", out)
126		}
127		after, err := listFiles(store)
128		if err != nil {
129			t.Fatal(err)
130		}
131		if len(after) != len(before) || after[0] != before[0] {
132			t.Fatalf("failure changed the store contents:\nbefore=%v\nafter=%v", before, after)
133		}
134		kept, err := os.ReadFile(existingPath)
135		if err != nil {
136			t.Fatal(err)
137		}
138		if !bytes.Equal(kept, existingBytes) {
139			t.Fatal("failure modified the existing report")
140		}
141	}
142	
143	// 合法的 false 输入仍然产生缺陷报告（回归保护）。
144	func TestCLIAuditExplicitFalseStillReportsDefect(t *testing.T) {
145		bin := auditBinary(t)
146		work := t.TempDir()
147		input := writeInput(t, work, "in.json", validInvariantInput)
148		store := filepath.Join(work, "reports")
149	
150		cmd := exec.Command(bin, "audit", "--input", input, "--store", store)
151		var stdout bytes.Buffer
152		cmd.Stdout = &stdout
153		var stderr bytes.Buffer
154		cmd.Stderr = &stderr
155		if err := cmd.Run(); err != nil {
156			t.Fatalf("explicit false must be a valid defect report: %v\n%s", err, stderr.String())
157		}
158		if !strings.Contains(stdout.String(), "发现缺陷") {
159			t.Fatalf("stdout must contain the defect report:\n%s", stdout.String())
160		}
161	}
162	
163	func listFiles(dir string) ([]string, error) {
164		entries, err := os.ReadDir(dir)
165		if err != nil {
166			return nil, err
167		}
168		names := make([]string, 0, len(entries))
169		for _, e := range entries {
170			names = append(names, e.Name())
171		}
172		return names, nil
173	}
